begin;
do $$
declare r text; s public.subscribers%rowtype;
begin
  r:=public.apply_subscription_lifecycle_event('checkout_pending','lifecycle-test@example.invalid','cus_fixture','sub_lifecycle_fixture',null,null,null,false,100);
  assert r='already_mapped';
  select * into s from public.subscribers where email='lifecycle-test@example.invalid';
  assert s.status='incomplete' and not s.stripe_payment_confirmed;
  r:=public.apply_subscription_lifecycle_event('subscription',null,'cus_fixture','sub_lifecycle_fixture','active','2030-01-01','price_fixture',false,101);
  assert r='applied';
  select * into s from public.subscribers where email='lifecycle-test@example.invalid';
  assert s.status='incomplete';
  assert public.apply_subscription_invoice_event('sub_lifecycle_fixture',100,120,true,'2030-01-01')='applied';
  select * into s from public.subscribers where email='lifecycle-test@example.invalid';
  assert s.status='active' and s.stripe_payment_confirmed;
  assert public.apply_subscription_lifecycle_event('subscription',null,'cus_fixture','sub_lifecycle_fixture','past_due','2030-01-01','price_fixture',false,110)='applied';
  select * into s from public.subscribers where email='lifecycle-test@example.invalid';
  assert s.status='active';
  assert public.apply_subscription_lifecycle_event('subscription',null,'cus_fixture','sub_lifecycle_fixture','active','2030-01-01','price_fixture',true,130)='applied';
  assert public.apply_subscription_lifecycle_event('subscription',null,'cus_fixture','sub_lifecycle_fixture','active','2030-01-01','price_fixture',false,125)='stale';
  assert public.apply_subscription_lifecycle_event('checkout_paid','lifecycle-test@example.invalid','cus_fixture','sub_lifecycle_fixture',null,null,null,false,135)='already_mapped';
  select * into s from public.subscribers where email='lifecycle-test@example.invalid';
  assert s.cancel_at_period_end;
  assert public.apply_subscription_lifecycle_event('subscription',null,'cus_fixture','sub_lifecycle_fixture','canceled','2030-01-01','price_fixture',false,140)='applied';
  assert public.apply_subscription_lifecycle_event('checkout_paid','lifecycle-test@example.invalid','cus_fixture','sub_lifecycle_fixture',null,null,null,false,145)='already_mapped';
  assert public.apply_subscription_lifecycle_event('subscription',null,'cus_fixture','sub_lifecycle_fixture','active','2030-01-01','price_fixture',false,150)='terminal';
  assert public.apply_subscription_invoice_event('sub_lifecycle_fixture',145,150,true,'2030-02-01')='ineligible';
  assert public.apply_subscription_lifecycle_event('checkout_paid','lifecycle-test@example.invalid','cus_fixture','sub_new_fixture',null,null,null,false,139)='conflict';
  assert public.apply_subscription_lifecycle_event('checkout_paid','lifecycle-test@example.invalid','cus_fixture','sub_new_fixture',null,null,null,false,160)='applied';
  select * into s from public.subscribers where email='lifecycle-test@example.invalid';
  assert s.stripe_subscription_id='sub_new_fixture' and s.status='active' and not s.cancel_at_period_end;
  assert public.apply_subscription_lifecycle_event('subscription',null,'cus_fixture','sub_new_fixture','active','2030-02-01','price_fixture',false,160)='applied';
  assert public.apply_subscription_lifecycle_event('subscription',null,'cus_fixture','sub_new_fixture','active','2030-02-01','price_fixture',false,160)='duplicate';
  assert public.apply_subscription_lifecycle_event('subscription',null,'cus_fixture','sub_new_fixture','past_due','2030-02-01','price_fixture',false,160)='ambiguous';
  assert public.apply_subscription_lifecycle_event('checkout_paid','lifecycle-test@example.invalid','cus_fixture','sub_other_fixture',null,null,null,false,170)='conflict';
  assert public.apply_subscription_lifecycle_event('subscription',null,'cus_unmapped','sub_unmapped_fixture','active','2030-01-01','price_fixture',false,170)='unmapped';
  assert not has_function_privilege('anon','public.apply_subscription_lifecycle_event(text,text,text,text,text,timestamptz,text,boolean,bigint)','execute');
  assert not has_function_privilege('authenticated','public.apply_subscription_lifecycle_event(text,text,text,text,text,timestamptz,text,boolean,bigint)','execute');
end $$;
select '26 lifecycle assertions passed; transaction rolled back' as validation;
rollback;
